const dialog=document.querySelector('#project-dialog');
function card(p,i){const a=document.createElement('article');a.className='project-card reveal';a.style.setProperty('--tint',p.tint);a.style.setProperty('--accent',p.accent);a.innerHTML=`<div class="project-art" aria-hidden="true"><div class="mock-window"><div class="mock-dots">● ● ●</div><div class="mock-title">${p.mock}</div><div class="mock-sub">${p.sub}</div>${p.bars?'<div class="mock-bars"><i style="height:28%"></i><i style="height:56%"></i><i style="height:43%"></i><i style="height:82%"></i><i style="height:100%"></i></div>':'<div class="mock-lines"><i></i><i></i><i></i></div>'}</div><span class="project-index">0${i+1}</span></div><div class="project-body"><p class="label project-meta">0${i+1} — ${p.type}</p><h3>${p.title}</h3><p>${p.short}</p><div class="tags">${p.tech.map(t=>`<span>${t}</span>`).join('')}</div><button class="details" aria-label="Read about ${p.title}">My contribution ↗</button></div>`;a.querySelector('button').addEventListener('click',()=>{dialog.querySelector('h2').textContent=p.title;dialog.querySelector('.dialog-tag').textContent=p.type;dialog.querySelector('.dialog-desc').textContent=p.detail;dialog.querySelector('.tags').innerHTML=p.tech.map(t=>`<span>${t}</span>`).join('');dialog.showModal()});return a}
projects.forEach((p,i)=>document.querySelector(i<3?'#featured-projects':'#more-projects').append(card(p,i)));
dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
